package com.bank.matching;

import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class SkipListDemo {
    private static final Logger LOG = Logger.getLogger("Matching");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        LOG.setUseParentHandlers(false);
        LOG.addHandler(h);
        LOG.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        OrderBook book = new OrderBook(LOG);
        Watchlist watchlist = new Watchlist();
        ExecutorService pool = Executors.newFixedThreadPool(4);

        String[] prices = {"2450.50", "2448.00", "2455.75", "2448.00", "2460.00", "2452.25"};
        CountDownLatch done = new CountDownLatch(prices.length);
        for (int i = 0; i < prices.length; i++) {
            String p = prices[i]; int id = i;
            pool.submit(() -> {
                book.addAsk(new Order("ORD" + id, "RELIANCE", new BigDecimal(p), 100));
                watchlist.add("RELIANCE");
                done.countDown();
            });
        }
        done.await(3, TimeUnit.SECONDS);

        LOG.info(() -> "Best ask (lowest price) = Rs." + book.bestAsk());
        LOG.info(() -> "Orders between 2448 and 2453 = "
            + book.ordersInBand(new BigDecimal("2448"), new BigDecimal("2453")));
        LOG.info(() -> "Watchlist (sorted) = " + watchlist.all());
        pool.shutdown();
    }
}

// ─── Would be in model/Order.java ───
record Order(String id, String symbol, BigDecimal price, int qty) {}

// ─── Would be in book/OrderBook.java ───
class OrderBook {
    // Keyed by price, natural ascending order → lowest ask first.
    private final ConcurrentSkipListMap<BigDecimal, Order> asks = new ConcurrentSkipListMap<>();
    private final Logger log;
    OrderBook(Logger log) { this.log = log; }

    void addAsk(Order o) {
        asks.put(o.price(), o);                         // O(log n), lock-free insert
        log.info(() -> "added ask " + o.id() + " @ Rs." + o.price());
    }

    BigDecimal bestAsk() {
        return asks.isEmpty() ? null : asks.firstKey(); // lowest price in O(log n)
    }

    // Range view: all orders with price in [from, to)
    Collection<Order> ordersInBand(BigDecimal from, BigDecimal to) {
        return asks.subMap(from, to).values();          // sorted live view
    }
}

// ─── Would be in watchlist/Watchlist.java ───
class Watchlist {
    private final ConcurrentSkipListSet<String> symbols = new ConcurrentSkipListSet<>();
    void add(String symbol) { symbols.add(symbol); }    // sorted + thread-safe
    Set<String> all() { return symbols; }
}
