package com.bank.matching.book;

import com.bank.matching.model.Order;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;

class OrderBookTest {
    @Test
    void bestAskIsLowestPriceAndRangeIsSorted() {
        OrderBook book = new OrderBook(java.util.logging.Logger.getLogger("t"));
        book.addAsk(new Order("A", "RELIANCE", new BigDecimal("2455"), 10));
        book.addAsk(new Order("B", "RELIANCE", new BigDecimal("2448"), 10));
        book.addAsk(new Order("C", "RELIANCE", new BigDecimal("2452"), 10));
        assertEquals(new BigDecimal("2448"), book.bestAsk());          // lowest wins
        assertEquals(2, book.ordersInBand(new BigDecimal("2448"),
                                          new BigDecimal("2455")).size()); // 2448,2452
    }
}
